[
  {
    "incident": {
      "component": "MongoDB (mongo-events-02)",
      "category": "Disk Space Exhaustion",
      "status": "firing",
      "summary": "Disk usage on mongo-events-02 has reached 88% and is not decreasing despite large document deletions."
    },
    "assessment": {
      "urgency": "high",
      "rationale": "Disk usage is at 88% with a steady growth rate. While currently a warning, if the growth rate accelerates or the available space is consumed, it will lead to a database outage."
    },
    "facts": [
      "Alert: MongoDBDiskSpaceLow on mongo-events-02:9216",
      "Environment: prod",
      "Current disk usage: 88%",
      "Filesystem size: 1TiB",
      "Available space: 123GiB",
      "Growth rate: 1GiB/h",
      "Replica set role: secondary",
      "Recent action: deleteMany on events collection removed ~50M documents",
      "Observation: Disk usage did not decrease after deletion"
    ],
    "missing_context": [
      {
        "item": "WiredTiger storage engine configuration",
        "why": "To determine if fragmentation or 'empty space' is being held by the engine rather than returned to the OS.",
        "how_to_check": "db.serverStatus().wiredTiger.block-manager"
      },
      {
        "item": "Oplog size and growth",
        "why": "To see if the deletion caused a massive oplog spike or if the oplog is consuming disproportionate space.",
        "how_to_check": "db.getReplicationInfo()"
      },
      {
        "item": "Disk I/O and fragmentation metrics",
        "why": "To check if the filesystem is fragmented or if there is high write pressure.",
        "how_to_check": "iostat -xz 1"
      }
    ],
    "immediate_actions": [
      {
        "action": "Do NOT run additional deleteMany operations",
        "purpose": "Prevent further fragmentation and unnecessary I/O load.",
        "conditions": "Immediate",
        "expected_effect": "Stabilization of disk usage growth.",
        "risks": "None, this is a preventative measure.",
        "requires_approval": false,
        "verify": "Check application logs for any automated cleanup scripts.",
        "rule_ids": [
          "DB_PREVENT_REDUNDANT_DELETES"
        ]
      },
      {
        "action": "Check disk space on Primary node",
        "purpose": "Determine if the issue is localized to this secondary or systemic across the replica set.",
        "conditions": "Immediate",
        "expected_effect": "Understanding the scope of the incident.",
        "risks": "None.",
        "requires_approval": false,
        "verify": "df -h on primary node",
        "rule_ids": [
          "REPLICA_SET_SCOPE_CHECK"
        ]
      }
    ],
    "investigation_steps": [
      {
        "step": "Verify WiredTiger internal free space",
        "hypothesis": "MongoDB has reclaimed the space internally (fragmentation) but has not released it to the OS.",
        "how_to_check": "db.stats().wiredTiger.fileSize vs db.stats().wiredTiger.dataSize"
      },
      {
        "step": "Analyze growth rate trends",
        "hypothesis": "The 1GiB/h growth rate is a temporary spike or a constant baseline.",
        "how_to_check": "Prometheus query: rate(node_filesystem_avail_bytes[6h])"
      }
    ],
    "root_cause_hypotheses": [
      "WiredTiger fragmentation: Deleting documents in MongoDB does not automatically shrink the data files on disk; it creates 'holes' (reusable space) within the files.",
      "Oplog growth: The massive deletion generated a large amount of oplog entries, potentially causing the oplog to grow if not capped correctly.",
      "Journaling/Log growth: Large deletions might have caused an increase in journal file size or system logs."
    ],
    "dangerous_operations": [
      {
        "operation": "Running 'compact' command",
        "why_dangerous": "The compact command is resource-intensive and can impact performance significantly; on older versions, it may lock the database.",
        "rule_id": "DB_COMPACT_RISK"
      },
      {
        "operation": "Running more 'deleteMany' operations",
        "why_dangerous": "Will increase fragmentation and potentially trigger more oplog growth without reclaiming disk space.",
        "rule_id": "DB_PREVENT_REDUNDANT_DELETES"
      }
    ],
    "applied_expert_rules": [
      "DB_PREVENT_REDUNDANT_DELETES",
      "REPLICA_SET_SCOPE_CHECK"
    ],
    "incident_update": "🚨 *Incident Update: MongoDB Disk Space Low* 🚨\nDetected 88% disk usage on `mongo-events-02` (secondary). Recent `deleteMany` operations did not reduce disk footprint, likely due to WiredTiger fragmentation. **Do not run further deletions.** Investigating if space is held internally or if oplog is growing. Monitoring growth rate (1GiB/h)."
  }
]
